<?php

use Modules\Inventory\Models\StockBalance;use Modules\Inventory\Models\StockReservation;use Modules\Production\Services\MaterialIssueService;use Modules\Receiving\Models\FabricRoll;
test('BR-060 actual issue memperbarui reservation dan balance roll sama',function(){[$u,$f,,$m,,$w,$mo]=shopFixture();$r=FabricRoll::where('roll_no','R001')->firstOrFail();$issue=app(MaterialIssueService::class)->issue($mo,$w->id,[['material_id'=>$f->id,'qty'=>80,'uom_id'=>$m->id,'roll_id'=>$r->id]],$u);$res=StockReservation::withoutGlobalScopes()->where('mo_id',$mo->id)->where('material_id',$f->id)->where('roll_id',$r->id)->firstOrFail();$bal=StockBalance::withoutGlobalScopes()->where('material_id',$f->id)->where('warehouse_id',$w->id)->where('roll_id',$r->id)->firstOrFail();expect($issue->mode)->toBe('ACTUAL')->and((float)$res->qty_issued)->toBe(80.0)->and($res->status)->toBe('PARTIAL_ISSUED')->and((float)$bal->on_hand)->toBe(220.0)->and((float)$bal->reserved)->toBe(120.0);});
test('BR-060 issue melebihi reservation ditolak',function(){[$u,$f,,$m,,$w,$mo]=shopFixture();$r=FabricRoll::where('roll_no','R001')->firstOrFail();app(MaterialIssueService::class)->issue($mo,$w->id,[['material_id'=>$f->id,'qty'=>201,'uom_id'=>$m->id,'roll_id'=>$r->id]],$u);})->throws(RuntimeException::class);
test('BR-041 fabric wajib roll reservation',function(){[$u,$f,,$m,,$w,$mo]=shopFixture();app(MaterialIssueService::class)->issue($mo,$w->id,[['material_id'=>$f->id,'qty'=>50,'uom_id'=>$m->id]],$u);})->throws(RuntimeException::class);
test('BR-041 backflush memakai target kumulatif',function(){[$u,,$trim,,, $w,$mo]=shopFixture();$mo->update(['qty_produced'=>100]);$issue=app(MaterialIssueService::class)->backflush($mo->fresh(),$w->id,$u);$bal=StockBalance::withoutGlobalScopes()->where('material_id',$trim->id)->where('warehouse_id',$w->id)->firstOrFail();$res=StockReservation::withoutGlobalScopes()->where('mo_id',$mo->id)->where('material_id',$trim->id)->firstOrFail();expect((float)$issue->lines->sum('qty'))->toBe(500.0)->and((float)$bal->on_hand)->toBe(500.0)->and((float)$res->qty_issued)->toBe(500.0)->and($res->status)->toBe('FULLY_ISSUED');});
